using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
class MeleeAnimationChecks {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(Game g,string n){return typeof(Game).GetField(n,F).GetValue(g);}static object Call(Game g,string n,params object[] a){return typeof(Game).GetMethod(n,F).Invoke(g,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);}static void Pump(int ms){var w=System.Diagnostics.Stopwatch.StartNew();while(w.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static void Shot(Control c,string name){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save("D:/WORK/Cet6Story/.validation/"+name+".png");}}
 [STAThread]static void Main(){try{Application.EnableVisualStyles();using(var g=new Game()){g.Opacity=0;g.Show();Pump(100);var save=new Save();typeof(Game).GetField("save",F).SetValue(g,save);save.toxicWoodland=ToxicWoodland.Create(0,save);var r=save.toxicWoodland;r.current=r.nodes.First(n=>n.kind=="battle").id;r.steps=2;r.mode="node-combat";Call(g,"ShowToxicWoodland");Call(g,"StopAudio");var run=r.combat;var b=run.partyBattle;b.phase="heroes";b.outcome=null;b.active="aelia";b.selectedHero=0;b.heroes[0].rank=1;b.enemies[0].rank=1;b.enemies[0].hp=110;b.enemies[0].dodge=0;Check(PartyCombat.BeginSkill(b,0,"slash",b.enemies[0].id),"begin melee");Call(g,"NextPartyQuestion",run);Call(g,"RenderPartyBattle",run);var canvas=(PartyBattleCanvas)Get(g,"partyCanvas");int hp=b.enemies[0].hp;Call(g,"AnswerPartyQuestion",run.question.answer);Check(canvas.IsCasting&&b.enemies[0].hp==hp,"damage deferred until hit");var timer=(Timer)typeof(PartyBattleCanvas).GetField("castTimer",F).GetValue(canvas);timer.Stop();System.Threading.Thread.Sleep(300);Check(b.enemies[0].hp==hp,"dash does not apply damage");Shot(canvas,"melee-dash-game");timer.Start();Pump(600);Check(b.enemies[0].hp<hp,"hit resolves before return completes");int hitHp=b.enemies[0].hp;Call(g,"AnswerPartyQuestion",run.question.answer);Check(b.enemies[0].hp==hitHp,"no duplicate hit");Pump(400);Check(!canvas.IsCasting&&canvas.Controls.OfType<BattleGlassPanel>().Any(),"return complete and result restored");var seq=new MeleeSequence{OriginalPosition=100,Destination=500};Check(seq.Position(seq.Duration)==100&&seq.Position(seq.WindupDuration+seq.DashDuration)==500,"exact endpoints");Check(seq.Position(490)>seq.Position(450)&&seq.Position(1160)<seq.Position(1100),"continuous directed dash and return");b.phase="defense-question";b.active=b.enemies[0].id;b.enemySkill="bite";b.enemyDamage=10;b.defenseTargets=new List<string>{"aelia"};b.defenseCursor=0;Call(g,"NextPartyQuestion",run);Call(g,"RenderPartyBattle",run);int heroHp=b.heroes[0].hp;Call(g,"AnswerPartyQuestion",run.question.answer);Check(canvas.IsCasting&&b.heroes[0].hp==heroHp,"monster melee also defers damage");Pump(1400);Check(b.heroes[0].hp<heroHp&&!canvas.IsCasting,"monster melee resolves and returns");g.Close();Console.WriteLine("PASS melee: deferred HP, no premature damage, single hit, full return, result restored, continuous motion");}}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
}
